question.solution:
class CircularQueue:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = [None] * capacity
        self.front = 0
        self.rear = 0

    def is_empty(self):
        return self.front == self.rear

    def is_full(self):
        return (self.rear + 1) % self.capacity == self.front

    def enqueue(self, x):
        if self.is_full():
            return False
        self.data[self.rear] = x
        self.rear = (self.rear + 1) % self.capacity
        return True

    def dequeue(self):
        if self.is_empty():
            return None
        value = self.data[self.front]
        self.data[self.front] = None
        self.front = (self.front + 1) % self.capacity
        return value

    def size(self):
        return (self.rear - self.front) % self.capacity

q = CircularQueue(3)
print(q.is_empty(), q.is_full())
print(q.enqueue(1), q.enqueue(2))
print(q.is_full(), q.enqueue(3))
print(q.dequeue(), q.dequeue(), q.dequeue())

